import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const container = new THREE.Group();

  // Get atlas texture with rendered text
  const atlasTexture = ctx.fontAtlas.texture;

  // Atlas region: [0, 0, 512, 320]
  const regionX = 0;
  const regionY = 0;
  const regionWidth = 512;
  const regionHeight = 320;
  const atlasWidth = 1024;
  const atlasHeight = 1024;

  // Create plane geometry with proper aspect ratio
  const planeHeight = 0.5;
  const planeWidth = planeHeight * (regionWidth / regionHeight);
  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

  // Adjust UVs to reference the correct atlas region
  const uvAttribute = geometry.getAttribute('uv');
  const uMin = regionX / atlasWidth;
  const vMin = regionY / atlasHeight;
  const uMax = (regionX + regionWidth) / atlasWidth;
  const vMax = (regionY + regionHeight) / atlasHeight;

  for (let i = 0; i < uvAttribute.count; i++) {
    const u = uvAttribute.getX(i);
    const v = uvAttribute.getY(i);
    uvAttribute.setXY(
      i,
      uMin + u * (uMax - uMin),
      vMin + v * (vMax - vMin)
    );
  }
  uvAttribute.needsUpdate = true;

  // Create material
  const material = new MeshBasicNodeMaterial({
    colorNode: texture(atlasTexture),
    transparent: true,
    side: THREE.DoubleSide,
  });

  // Create and position mesh
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(0, 1, 0.06);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  container.add(mesh);

  // Apply cinematic primitives
  if (config.cinematicPrimitives && config.cinematicPrimitives.length > 0) {
    for (const primitive of config.cinematicPrimitives) {
      const primFn = ctx.primitives[primitive.name];
      if (primFn) {
        primFn(container, primitive.params || {});
      }
    }
  }

  // Setup event handlers
  container.userData.handlers = {};

  // Cleanup
  container.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    gsap.killTweensOf(mesh);
    gsap.killTweensOf(container);
  };

  return container;
}
